      "DocumentHandoffEvidence": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "kind": {
            "const": "document"
          },
          "source_id": {
            "type": "string",
            "minLength": 1
          },
          "project_id": {
            "type": "string",
            "minLength": 1
          },
          "document_id": {
            "type": "string",
            "minLength": 1
          },
          "version_id": {
            "type": "string",
            "minLength": 1
          },
          "passage_id": {
            "type": "string",
            "minLength": 1
          },
          "permission_revision": {
            "type": "string",
            "pattern": "^[1-9][0-9]*$"
          },
          "lifecycle_revision": {
            "type": "string",
            "pattern": "^[1-9][0-9]*$"
          },
          "version_digest": {
            "type": "string",
            "pattern": "^[a-f0-9]{64}$",
            "description": "Lowercase SHA-256 over the exact specified bytes; no normalization or JSON reserialization."
          },
          "excerpt_digest": {
            "type": "string",
            "pattern": "^[a-f0-9]{64}$",
            "description": "Lowercase SHA-256 over the exact specified bytes; no normalization or JSON reserialization."
          }
        },
