          "purpose",
          "actor_id",
          "project_id",
          "access_context_ref",
          "session_generation",
          "project_permission_revision",
          "evidence_set",
          "payload_digest",
          "payload_length",
          "destination_ref",
          "prepared_at",
          "complete"
        ]
      },
      "StoredHandoff": {
        "type": "object",
        "additionalProperties": false,
        "properties": {
          "manifest": {
            "$ref": "#/components/schemas/HandoffManifest"
          },
          "manifest_bytes_base64": {
            "type": "string",
            "minLength": 1,
            "contentEncoding": "base64"
          },
          "manifest_digest": {
            "type": "string",
            "pattern": "^[a-f0-9]{64}$",
            "description": "Lowercase SHA-256 over the exact specified bytes; no normalization or JSON reserialization."
          },
          "durable_commit_ref": {
            "type": "string",
            "minLength": 1
          }
        },
        "required": [
          "manifest",
          "manifest_bytes_base64",
          "manifest_digest",
          "durable_commit_ref"
        ],
        "description": "Knowledge-owned immutable committed manifest receipt. Decode manifest_bytes_base64 as UTF-8 JSON equal to manifest; manifest_digest hashes those exact bytes. Resolve by authenticated getHandoffManifest and compare the entire stored record before claiming. A caller assertion, digest or complete=true is never evidence of persistence or current access."
      },
